text:
{
  "results": [
    {
      "title": "太上正一盟威朝仪",
      "verdict": "partial",
      "issue": "No independent text of this exact title in Zhengtong Daozang; related 正一朝仪/盟威 materials appear only in ordination/liturgy strata. Claim is cautious and catalog-aligned but cannot be fully confirmed as a named standalone work."
    },
    {
      "title": "太上说豁落七元经",
      "verdict": "partial",
      "issue": "Standard Daozang title is usually 北帝说豁落七元经 (or close variants), not 太上说… Exact title form is slightly off; content description (Beidi, Qiyuan talismans, Beidou, lamps, memorials) is broadly correct."
    },
    {
      "title": "灵宝施食科仪",
      "verdict": "partial",
      "issue": "Closest Zhengtong/Xu Daozang match is often cited as 灵宝施食法 rather than this exact title; ritual outline is plausible but title and ‘nearest’ identification are approximate."
    },
    {
      "title": "历世真仙体道通鉴后编",
      "verdict": "partial",
      "issue": "Main series is 正编 (DZ296), 续编 (DZ297), 后集 (DZ298); ‘后编’ is not the standard catalog title. Content note on female immortals in 后集 is broadly right, but naming is imprecise."
    },
    {
      "title": "太清阴阳五行经",
      "verdict": "partial",
      "issue": "No secure Zhengtong Daozang / Schipper–Verellen hit for this exact title; ‘lost, misnamed, or scattered Taiqing/wuxing material’ is a reasonable non-claim rather than a false positive."
    },
    {
      "title": "黄帝太一八门逆顺生死诀",
      "verdict": "partial",
      "issue": "A short Dongxuan/shuzhong-style Taiyi Eight Gates text with mixed arts and a later Taiyin Xuannü section is attested in catalogs, but exact DZ number, division, and structure details need tighter source pinning."
    },
    {
      "title": "上清太极隐注玉经宝诀",
      "verdict": "partial",
      "issue": "Known ancient Lingbao (though Shangqing-titled) work on scripture reception/recitation is real; ‘one juan + full ritual inventory’ is directionally right but depends on which recension is meant."
    },
    {
      "title": "太上灵宝胞胎经",
      "verdict": "partial",
      "issue": "Exact title not securely verified in Zhengtong Daozang; embryo/birth themes exist elsewhere in early Lingbao, but identity with this name remains unproven."
    },
    {
      "title": "太上说消魔经",
      "verdict": "partial",
      "issue": "No single short-title text; nearest are multiple xiaomo scriptures (e.g. 洞真太上说智慧消魔真经). Correct as a title-cluster note, not a unique work."
    },
    {
      "title": "太上说西王母益算经",
      "verdict": "partial",
      "issue": "Exact title not confirmed in Zhengtong Daozang; Xiwangmu / yisuan longevity themes exist in other works, so absence claim is fair but negative evidence is incomplete."
    },
    {
      "title": "谷神篇",
      "verdict": "partial",
      "issue": "Yuan neidan work by Lin Yuan (Xuanchaozi), two juan, is standard; Dongzhen fangfa placement and doctrinal summary are broadly right, but finer catalog claims were not exhaustively rechecked against Schipper numbers."
    },
    {
      "title": "还丹众仙论",
      "verdict": "partial",
      "issue": "Yang Zai / ca. 1052 one-juan compilation of many masters is widely accepted; list of names and section placement are plausible but some master attributions in the blurb may be traditional rather than critically verified."
    },
    {
      "title": "老子节解",
      "verdict": "partial",
      "issue": "Attributed to Ge Xuan in bibliographic tradition (e.g. Songshi entry); no complete Zhengtong Daozang text. Transmission and modern Yan Lingfeng reconstitutions are correctly flagged as uncertain."
    },
    {
      "title": "灵棋经",
      "verdict": "partial",
      "issue": "Identity with 灵棋本章正经, two juan, 124-ish hexagram-style casts is correct; authorship as Eastern Jin monk Fǎwèi (per Yu Jiaxi) vs. later Yan/He commentary chain is debated scholarship, so ‘author = Fǎwèi’ is stronger than fully settled."
    },
    {
      "title": "三洞众戒文",
      "verdict": "partial",
      "issue": "Zhang Wanfu compilation of Three Caverns precept texts is real; original two juan / Daozang amalgamation and the long list of precept sets are broadly right but item-by-item inventory may be incomplete or reorder-simplified."
    },
    {
      "title": "太清玉炉经",
      "verdict": "partial",
      "issue": "No confirmed Zhengtong Daozang text under this exact title in common digital catalogs; cautious ‘unverified / possibly non-canonical’ stance is appropriate, not a positive false identification."
    },
    {
      "title": "上清丹元玉经",
      "verdict": "partial",
      "issue": "Closest match is usually 上清丹元玉真帝皇飞仙上经 (often DZ404 in Schipper/Komjathy numbering). User short title is approximate; Dongxuan yujue vs Dongzhen labeling correction is the main partial point."
    },
    {
      "title": "太上说洪恩灵济真君妙经",
      "verdict": "partial",
      "issue": "Canonical full title is typically 灵宝天尊说洪恩灵济真君妙经; Yongle imperial preface and Xu brothers / Hong’en Lingji cult are correct. Short title ‘太上说…’ is a near-title, not the exact catalog form."
    },
    {
      "title": "太上说十一曜大消灾神咒经",
      "verdict": "partial",
      "issue": "Standard title is 元始天尊说十一曜大消灾神咒经; content on eleven luminaries is right. Short ‘太上说…’ form is a common near-title, not the catalog lemma."
    },
    {
      "title": "道德真经取善集",
      "verdict": "partial",
      "issue": "Li Lin’s 取善 anthology is real; Dongshen yujue (not Taiqing) placement is the important correction already stated. Commentator roster is selective, not exhaustive."
    },
    {
      "title": "太上老君说牛王妙经",
      "verdict": "partial",
      "issue": "Folk Niuwang scripture, mainly shanshu/local print, not confirmed in Zhengtong Daozang catalogs—fair negative claim; ‘sometimes with Mazu’ is regionally variable and not a fixed feature."
    },
    {
      "title": "太上三十六部尊经",
      "verdict": "partial",
      "issue": "Six juan, 36 short scriptures in three pure realms × 12, Buddhist–Daoist hybrid language is standard; exact Daozang numbering (‘提要号 8’) and doctrinal summary are slightly simplified."
    },
    {
      "title": "上清九真中经（上清太上帝君九真中经）",
      "verdict": "partial",
      "issue": "Early Shangqing Nine Perfected visualization text is correctly identified; full alternate title and methods (nine palaces, five viscera, solar-lunar ‘奔’ techniques) are right in outline, details truncated/partial."
    },
    {
      "title": "太上灵宝十部经",
      "verdict": "partial",
      "issue": "Correct that this is a collective label for the early Lingbao corpus (ten sections / multi-juan set), not a single independent Zhengtong entry under that exact short title."
    },
    {
      "title": "玄天上帝报恩经（玄天上帝说报父母恩重经）",
      "verdict": "partial",
      "issue": "Full title 玄天上帝说报父母恩重经 and Zhenwu filial-piety theme are right; Zhao Yizhen colophon attachment is often cited but should be treated as traditional apparatus, not always critically secure in every edition."
    },
    {
      "title": "太上洞玄灵宝天童经（近题：太上太清天童护命妙经）",
      "verdict": "partial",
      "issue": "Correct that the short Lingbao-titled form is not the standard Daozang lemma; canonical is 太上太清天童护命妙经 (DZ632). Maoshan / Liang Wuzhen / Daguan-year transmission is legendary framing, not hard history."
    },
    {
      "title": "太上说大帝延寿妙经（近题：太上灵宝天尊说延寿妙经）",
      "verdict": "partial",
      "issue": "Near-title mapping to 太上灵宝天尊说延寿妙经 (DZ382) is sound; ‘大帝延寿’ is not the catalog title. Content summary is truncated/generic."
    },
    {
      "title": "太上说五圣始生真经（近题：大惠静慈妙乐天尊说福德五圣经）",
      "verdict": "partial",
      "issue": "Correct that ‘五圣始生’ is not the catalog title; standard is 大惠静慈妙乐天尊说福德五圣经 (DZ1192). Content claim is only outline-level."
    },
    {
      "title": "抱朴子內篇",
      "verdict": "partial",
      "issue": "Ge Hong authorship and centrality of waidan/immortality arts are accurate; calling it purely ‘外丹’ understates its broader argumentative scope (philosophy, critique, many techniques)."
    },
    {
      "title": "道樞",
      "verdict": "partial",
      "issue": "Zeng Zao, 42 juan, Zhiyouzi summaries—standard. ‘Pre–Southern Song encyclopedia of yangsheng/neidan’ is roughly right for this compilation’s horizon, but dating/content scope is broader than neidan alone."
    },
    {
      "title": "雷法議玄篇",
      "verdict": "partial",
      "issue": "Shenxiao thunder-rite theory text with emphasis on simplicity and qi/star/hand/seal methods is real; ‘萬宗師等’ as author line is traditional/collective and needs finer attribution than a single named master."
    },
    {
      "title": "清微神烈秘法",
      "verdict": "partial",
      "issue": "Qingwei thunder-rite manual (origins, seats, meditation, talismans) is correctly typed; anonymous/Qingwei-school attribution is fine, but internal structure summary is high-level only."
    },
    {
      "title": "海瓊白真人語錄",
      "verdict": "partial",
      "issue": "Bai Yuchan sayings compiled by disciples (Peng Si et al.) is standard; neidan/thunder/Chan fusion description is fair but not exhaustive of the collection’s genres."
    },
    {
      "title": "洞神八帝妙精經",
      "verdict": "partial",
      "issue": "Dongshen / Three Sovereigns text on Nine Sovereigns and eight precepts is the usual identification; ‘keystone of Dongshen’ is evaluative and slightly overstated without source hierarchy."
    },
    {
      "title": "漢天師世家",
      "verdict": "partial",
      "issue": "Zhang Zhengchang with later Zhang Guoxiang continuation, Zhengyi Tianshi genealogy into Ming, Xu Daozang inclusion—broadly correct; exact redaction layers and legendary vs historical mix are more complex."
    },
    {
      "title": "呂祖志",
      "verdict": "partial",
      "issue": "Ming-era Lü Dongbin anthology (vita, miracles, poems, danfa materials) is right; anonymity and Quanzhen–neidan framing are acceptable but edition history is multi-layered."
    },
    {
      "title": "正一法文經章官品",
      "verdict": "partial",
      "issue": "Surviving Zhengyi Fawen fragment listing petition officers is correctly characterized; ‘hundreds of officers’ and full functional list are summary-level, not a critical inventory."
    },
    {
      "title": "徐仙翰藻",
      "verdict": "partial",
      "issue": "Chen Menggen compilation on Fujian Xu-immortal (Xu brothers) cult, in Xu Daozang, is right; genre mix (sacrificial prose, poetry, miracle records) is accurate in outline."
    },
    {
      "title": "葛仙翁肘後備急方",
      "verdict": "partial",
      "issue": "Ge Hong base with Tao Hongjing and Yang Yongdao layers is the standard textual history; ‘Dao–medicine crossover’ is fair, but it is primarily a medical emergency formulary, not a Daozang scripture per se."
    },
    {
      "title": "紫微斗數",
      "verdict": "partial",
      "issue": "Xu Daozang Ziwei Doushu materials exist; describing ‘the’ book as a single anonymous classic oversimplifies a technical tradition with multiple manuals and later strata."
    },
    {
      "title": "海瓊問道集",
      "verdict": "partial",
      "issue": "Bai Yuchan–related Q&A collection complementing the yulu is accepted; disciple compilation and Nanzong dialogue pedagogy are right in outline."
    },
    {
      "title": "丹房須知",
      "verdict": "partial",
      "issue": "Wu Wu (Ziranzi), Southern Song lab manual on site, chamber, taboos, tools—standard. Emphasis on preparation over recipes is correct; finer dating details vary by source."
    },
    {
      "title": "龍虎還丹訣",
      "verdict": "partial",
      "issue": "Jinlingzi two-juan waidan long–hu (cinnabar–mercury) treatise is the usual ID; technical summary is directionally right but compressed."
    },
    {
      "title": "太極真人九轉還丹經要訣",
      "verdict": "partial",
      "issue": "Anonymous, Xicheng Wangjun oral-formula framing, nine-cycle waidan with specific mineral sequence is standard for this title; 90-day fire phasing and prep powders are traditional contents claims needing edition-level check."
    },
    {
      "title": "還丹肘後訣",
      "verdict": "partial",
      "issue": "Three-juan anonymous work (Ge Hong pseudepigrapha common), mix of theory and song-jue, is catalog-consistent; specific ‘one thing becomes two’ and ‘heaven-tally cycle’ slogans are traditional jargon, verification is partial."
    },
    {
      "title": "諸家神品丹法",
      "verdict": "partial",
      "issue": "Six-juan multi-source waidan anthology is correctly typed; ‘Song and earlier’ diversity claim is fair at handbook level."
    },
    {
      "title": "鉛汞甲庚至寶集成",
      "verdict": "partial",
      "issue": "Five-juan lead–mercury / jia-geng ‘ultimate treasure’ compilation is the standard description; alchemical-system claims are summary-level."
    },
    {
      "title": "丹房奧論",
      "verdict": "partial",
      "issue": "Song-period danfang ‘secret discussion’ on true medicines/fire etc. exists in the corpus; entry text here is truncated mid-sentence so content claim cannot be fully verified as stated."
    },
    {
      "title": "太上洞玄靈寶智慧本願大戒上品經",
      "verdict": "partial",
      "issue": "Early Lingbao precept scripture in Q&A form (Taiji/Ge Xuan line) is correctly identified; ‘Xu Laile as Taiji fashi’ and vow–karma linkage are standard but details abbreviated."
    },
    {
      "title": "太極真人敷靈寶齋戒威儀諸經要訣",
      "verdict": "partial",
      "issue": "Early Lingbao zhai ritual essentials, sometimes linked to Zheng Yin recording tradition, is right in type; comparative references to Daode/Dadong are traditional framing."
    },
    {
      "title": "太上洞玄靈寶三元玉京玄都大獻經",
      "verdict": "partial",
      "issue": "Lingbao Ullambana-style Three Primes / Xuandu great offering scripture is correctly characterized; ‘Liu Wudai forged’ is one scholarly hypothesis, not consensus fact—hence partial."
    },
    {
      "title": "黃帝授三子玄女經",
      "verdict": "partial",
      "issue": "Ancient shifa / marriage-timing text in the Xuannü–Huangdi orbit, related to longshou-type materials, is right; specific spirit names and full method set are only sketched."
    },
    {
      "title": "靈臺經",
      "verdict": "partial",
      "issue": "Short Dongzhen astronomical/astrological ‘Lingtai’ text is a real rare type in Zhengtong Daozang; content description is generic."
    },
    {
      "title": "秤星靈臺祕要經",
      "verdict": "partial",
      "issue": "Companion ‘weighing stars / repelling baleful stars’ manual is correctly typed; section titles cited are plausible but not exhaustively verified here."
    },
    {
      "title": "周氏冥通記",
      "verdict": "partial",
      "issue": "Zhou Ziliang’s spirit-communication diary edited by Tao Hongjing is securely identified; ‘living Shangqing master–disciple document’ is accurate in spirit, details of redaction partial."
    },
    {
      "title": "太上黃籙齋儀",
      "verdict": "partial",
      "issue": "Du Guangting’s large Yellow Register zhai liturgy is correctly attributed; multi-day session structure and salvation uses are right in outline."
    },
    {
      "title": "無上黃籙大齋立成儀",
      "verdict": "partial",
      "issue": "Jiang Shuyu compilation from Liu Yongguang transmission, 57 juan magisterial Yellow Register code, is standard; lineage Lù Xiujing–Du–… is schematic inheritance, not a simple single chain."
    },
    {
      "title": "洞玄靈寶齋說光燭戒罰燈祝願儀",
      "verdict": "partial",
      "issue": "Lu Xiujing Lingbao zhai text on lamps, penalties, and vows is correctly placed; functional importance is fair, wording is evaluative."
    },
    {
      "title": "太上洞玄靈寶授度儀",
      "verdict": "partial",
      "issue": "Lu Xiujing’s Lingbao ordination/transmission liturgy with memorial preface is standard; ‘model for later registers’ is historical judgment, broadly accepted."
    },
    {
      "title": "玉音法事",
      "verdict": "partial",
      "issue": "Song (Huizong-era system) Daoist ritual music / hymn collection is correctly typed; anonymity and Dongxuan praise category are catalog-consistent at summary level."
    }
  ]
}
